import React, { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './CSS/Home.css';

function Home({ onSelectProduct }) {
  const navigate = useNavigate();
  const scrollRef1 = useRef(null);
  const scrollRef2 = useRef(null);
  const scrollRef3 = useRef(null);

  const [wishlistItems, setWishlistItems] = useState([]);
  const [showWishlistDropdown, setShowWishlistDropdown] = useState(false);

  // Default fallback top picks
  const defaultTopPicks = [
    { id: 1, title: 'Pigeon Amaze Plus Electric Kettle', price: '499', originalPrice: '$1,245', rating: '4.0', reviews: '179,344', image: 'https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=300' },
    { id: 2, title: 'Clazkit Water Bottle Stainless Steel', price: '159', originalPrice: '$299', rating: '4.0', reviews: '2,383', image: 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?w=300' },
    { id: 3, title: 'GNASTAS Kitchen Utility Knife', price: '709', originalPrice: '$1,499', rating: '4.3', reviews: '101', image: 'https://images.unsplash.com/photo-1593618998160-e34014e67546?w=300' },
    { id: 4, title: 'Pigeon Kessel Multipurpose Kettle', price: '949', originalPrice: '$1,695', rating: '3.8', reviews: '30,147', image: 'https://images.unsplash.com/photo-1585515320310-259814833e62?w=300' },
    { id: 5, title: 'Amazon Basics Electric Egg Boiler', price: '429', originalPrice: '$650', rating: '4.1', reviews: '13,391', image: 'https://images.unsplash.com/photo-1584269600464-37b1b58a9fe7?w=300' },
    { id: 6, title: 'AERYS Digital Alarm Clock with LED', price: '284', originalPrice: '$1,999', rating: '3.9', reviews: '7,947', image: 'https://images.unsplash.com/photo-1563861826100-9cb868fdbe1c?w=300' },
    { id: 7, title: 'Noise Buds VS104 Truly Wireless', price: '999', originalPrice: '$2,999', rating: '4.2', reviews: '45,210', image: 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=300' },
    { id: 8, title: 'Milton Thermosteel Flip Lid Flask', price: '675', originalPrice: '$999', rating: '4.5', reviews: '12,500', image: 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?w=300' },
    { id: 9, title: 'Boldfit Gym Shaker Bottle for Workout', price: '249', originalPrice: '$599', rating: '4.3', reviews: '8,120', image: 'https://images.unsplash.com/photo-1544816155-12df9643f363?w=300' },
  ];

  const [topPicks, setTopPicks] = useState(defaultTopPicks);

  // Load wishlist and dynamic seller products on mount & listen for updates
  useEffect(() => {
    const fetchWishlist = () => {
      const saved = JSON.parse(localStorage.getItem('wishlistItems')) || [];
      setWishlistItems(saved);
    };

    const fetchProducts = () => {
      const savedProducts = JSON.parse(localStorage.getItem('sellerProducts')) || [];
      if (savedProducts.length > 0) {
        setTopPicks(savedProducts);
      }
    };

    fetchWishlist();
    fetchProducts();

    window.addEventListener('wishlistUpdated', fetchWishlist);
    window.addEventListener('productUpdated', fetchProducts);
    window.addEventListener('storage', fetchWishlist);
    window.addEventListener('storage', fetchProducts);

    return () => {
      window.removeEventListener('wishlistUpdated', fetchWishlist);
      window.removeEventListener('productUpdated', fetchProducts);
      window.removeEventListener('storage', fetchWishlist);
      window.removeEventListener('storage', fetchProducts);
    };
  }, []);

  const handleRemoveFromWishlist = (id, e) => {
    e.stopPropagation();
    const updated = wishlistItems.filter(item => (item._id || item.id) !== id);
    setWishlistItems(updated);
    localStorage.setItem('wishlistItems', JSON.stringify(updated));
    window.dispatchEvent(new Event('wishlistUpdated'));
  };

  const browsingHistory = [
    { id: 101, title: 'iPhone Pro Max (2 TB) - Silver', price: '3,29,900', rating: '4.5', reviews: '15', image: 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=300' },
    { id: 102, title: 'SONISHA Women Floral Print Short Kurti', price: '440.82', originalPrice: '$1,799', rating: '4.0', reviews: '14', image: 'https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?w=300' },
    { id: 103, title: 'Story@Home King Size Bedsheet', price: '849.00', originalPrice: '$999', rating: '4.2', reviews: '33', image: 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=300' },
    { id: 104, title: '40W Dynamic Power Adapter with 60W Max', price: '4,490.00', rating: '4.6', reviews: '8', image: 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=300' },
    { id: 105, title: 'JETech Matte Case for iPhone Pro', price: '1,299.00', originalPrice: '$2,099', rating: '4.4', reviews: '10,014', image: 'https://images.unsplash.com/photo-1601784551446-20c9e07cdbdb?w=300' },
    { id: 106, title: 'JBL Go 3 Portable Wireless Speaker', price: '2,999.00', originalPrice: '$3,999', rating: '4.6', reviews: '18,400', image: 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=300' },
    { id: 107, title: 'Logitech Wireless Mouse M220', price: '695.00', originalPrice: '$995', rating: '4.4', reviews: '32,100', image: 'https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?w=300' },
  ];

  const relatedItems = [
    { id: 201, title: 'boAt Rockerz 450 Bluetooth Headphones', price: '1,499', originalPrice: '$3,990', rating: '4.2', reviews: '85,420', image: 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=300' },
    { id: 202, title: 'Fire-Boltt Phoenix Smart Watch', price: '1,199', originalPrice: '$9,999', rating: '4.1', reviews: '42,150', image: 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=300' },
    { id: 203, title: 'ZEBRONICS Zeb-County Bluetooth Speaker', price: '469', originalPrice: '$799', rating: '4.0', reviews: '19,830', image: 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=300' },
    { id: 204, title: 'Milton Go Fit Steel Bottle 750ml', price: '499', originalPrice: '$650', rating: '4.5', reviews: '5,120', image: 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?w=300' },
    { id: 205, title: 'Boldfit Yoga Mat with Carrying Strap', price: '699', originalPrice: '$1,499', rating: '4.3', reviews: '11,400', image: 'https://images.unsplash.com/photo-1601925260368-ae2f83cf8b7f?w=300' },
    { id: 206, title: 'Portronics Adapto 20W Fast Charger', price: '349', originalPrice: '$999', rating: '4.1', reviews: '9,820', image: 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=300' },
    { id: 207, title: 'Zebronics Zeb-Solaris Wireless Mouse', price: '399', originalPrice: '$749', rating: '4.0', reviews: '4,150', image: 'https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?w=300' },
    { id: 208, title: 'Realme TechLife Buds T100', price: '1,299', originalPrice: '$2,999', rating: '4.3', reviews: '22,410', image: 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=300' },
  ];

  const renderProductRow = (title, items, ref, pageInfo, darkTheme = false) => (
    <div className={`product-row-wrapper ${darkTheme ? 'dark-theme' : 'light-theme'}`}>
      <div className="product-row-header">
        <div className="product-header-left">
          <h2 className={`product-row-title ${darkTheme ? 'dark-title' : 'light-title'}`}>{title}</h2>
          <Link to="/products" className="explore-link">Explore more deals</Link>
        </div>
        {pageInfo && <span className="page-info-text">{pageInfo}</span>}
      </div>

      <div ref={ref} className="products-scroll-box">
        {items.map((product) => (
          <div 
            key={product._id || product.id} 
            className="product-card-item"
            onClick={() => onSelectProduct && onSelectProduct(product)}
            style={{ cursor: 'pointer' }}
          >
            <div className="product-image-box">
              <img src={product.image || product.images?.[0]} alt={product.title || product.name} className="product-img" />
            </div>
            <p className="product-card-title">{product.title || product.name}</p>
            <div className="product-rating-box">
              <span className="product-stars">★★★★☆</span>
              <span className="product-reviews">{product.reviews || '4.5'}</span>
            </div>
            <div className="product-price-container">
              <span className="product-price-current">${product.price}</span>
              {product.originalPrice && <span className="product-price-original">{product.originalPrice}</span>}
            </div>
            <p className="product-delivery-text">FREE delivery <b>Thu, 1 Oct</b></p>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="home-page-container" style={{ position: 'relative' }}>
      
      <div style={{
        position: 'absolute',
        top: '15px',
        right: '25px',
        zIndex: 100,
        display: 'flex',
        alignItems: 'center',
        gap: '20px'
      }}>
        <div style={{ position: 'relative' }}>
          {showWishlistDropdown && (
            <div style={{
              position: 'absolute',
              right: 0,
              top: '52px',
              width: '320px',
              backgroundColor: '#ffffff',
              borderRadius: '12px',
              boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.2)',
              border: '1px solid #e2e8f0',
              zIndex: 1000,
              padding: '16px',
              color: '#0f172a'
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px', borderBottom: '1px solid #f1f5f9', paddingBottom: '8px' }}>
                <h4 style={{ margin: 0, fontSize: '16px', fontWeight: 'bold' }}>My Wishlist ({wishlistItems.length})</h4>
                <button 
                  onClick={() => setShowWishlistDropdown(false)}
                  style={{ background: 'none', border: 'none', fontSize: '16px', cursor: 'pointer', color: '#64748b' }}
                >
                  &times;
                </button>
              </div>

              {wishlistItems.length === 0 ? (
                <p style={{ textAlign: 'center', color: '#64748b', fontSize: '14px', margin: '20px 0' }}>Your wishlist is empty.</p>
              ) : (
                <div style={{ maxHeight: '250px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '10px' }}>
                  {wishlistItems.map((item) => (
                    <div 
                      key={item._id || item.id} 
                      style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '6px', borderRadius: '8px', background: '#f8fafc' }}
                    >
                      <img 
                        src={item.image || item.images?.[0]} 
                        alt={item.title || item.name} 
                        style={{ width: '45px', height: '45px', objectFit: 'contain', borderRadius: '6px', background: '#fff' }} 
                      />
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <p style={{ margin: 0, fontSize: '13px', fontWeight: '600', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                          {item.title || item.name}
                        </p>
                        <span style={{ fontSize: '12px', color: '#6366f1', fontWeight: 'bold' }}>${item.price}</span>
                      </div>
                      <button 
                        onClick={(e) => handleRemoveFromWishlist(item._id || item.id, e)}
                        style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', fontSize: '14px', padding: '4px' }}
                        title="Remove"
                      >
                        <i className="fa-solid fa-trash"></i>
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <button 
                onClick={() => {
                  setShowWishlistDropdown(false);
                  navigate('/wishlist');
                }}
                style={{
                  width: '100%',
                  marginTop: '12px',
                  backgroundColor: '#130352',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '6px',
                  padding: '8px',
                  fontWeight: 'bold',
                  fontSize: '13px',
                  cursor: 'pointer'
                }}
              >
                View Full Wishlist Page
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="home-hero-banner-box">
        <div className="hero-banner-content">
          <span className="hero-badge-tag">Sale is live</span>
          <h1 className="hero-main-title">Starting $49</h1>
          <h2 className="hero-sub-title">Home, kitchen, toys & outdoors</h2>
          <Link to="/products" className="hero-return-btn">
            Return to all deals
          </Link>
        </div>

        <div className="hero-banner-img-box">
          <img 
            src="https://images.unsplash.com/photo-1526170375885-4d8ecf77b99f?w=600" 
            alt="Promotion Banner" 
            className="hero-banner-img"
          />
        </div>
      </div>

      {renderProductRow("Top picks", topPicks, scrollRef1, null, true)}
      {renderProductRow("Inspired by your browsing history", browsingHistory, scrollRef2, "Page 1 of 6", false)}

      <div className="middle-promo-banner">
        <div>
          <span className="promo-badge">Limited Time Deal</span>
          <h2 className="promo-title">Up to 60% off | Electronics & Accessories</h2>
          <p className="promo-description">Explore top brands with no cost EMI and exchange offers.</p>
        </div>
        <Link to="/products" className="promo-shop-btn">
          Shop Now
        </Link>
      </div>

      {renderProductRow("Related to items you viewed", relatedItems, scrollRef3, "Page 1 of 6", false)}
    </div>
  );
}

export default Home;
